import operator
from PIL import Image, ImageEnhance, ImageChops


class ImageProcessor:
    MAGIC_NUMBER_MAX_DEGREES = 360

    def __init__(self):
        self._image = None

    @property
    def image(self):
        return self._image

    @image.setter
    def image(self, value):
        self._image = value

    def _require_image(self):
        if not self.image:
            raise ValueError("No image loaded")

    def load_image(self, image_path):
        self.image = Image.open(image_path)

    def save_image(self, save_path):
        if self.image:
            self.image.save(save_path)

    def resize_image(self, width, height):
        self._require_image()
        self.image = self.image.resize((width, height))

    def rotate_image(self, degrees):
        self._require_image()
        normalized_degrees = self._normalize_degrees(degrees)
        self.image = self.image.rotate(normalized_degrees)

    def _normalize_degrees(self, degrees):
        if degrees > self.MAGIC_NUMBER_MAX_DEGREES:
            return degrees % 360
        return degrees

    def adjust_brightness(self, factor):
        self._require_image()
        self.image = self._apply_brightness_enhancement(self.image, factor)

    def _apply_brightness_enhancement(self, image, factor):
        enhancer = ImageEnhance.Brightness(image)
        return enhancer.enhance(factor)
